// ── Build review message ─────────────────────────────────────────
// Everything a reviewer needs to decide, and NO claimant contact details: this
// execution is stored in n8n's database while it waits for the reviewer.
const r = $input.first().json;
const claimRef = $('Review_Trigger').first().json.claim_ref;
if (!r.claim_ref) throw new Error(`Fraud review: claim ${claimRef} not found`);
if (r.status !== 'pending_fraud_review') {
  // Already decided (or re-routed) by the time we got here: nothing to ask.
  return [];
}

const money = (n) => 'R ' + Number(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const policyAgeDays = Math.round(DateTime.fromISO(r.incident_date).diff(DateTime.fromISO(r.policy_start), 'days').days);
const pct = Math.round((r.claimed_amount / r.sum_insured) * 100);
const flags = (r.rule_flags || []).map((f) => `  - ${f.code}${f.points ? ` (+${f.points})` : ''}: ${f.detail}`);
const indicators = (r.ai_fraud_indicators || []).join(', ') || 'none';
const reasons = (r.route_reasons || []).map((x) => `  - ${x}`);

const message = [
  `Claim ${r.claim_ref} needs a fraud review.`,
  '',
  'CLAIM',
  `  Product:          ${r.product}`,
  `  Amount claimed:   ${money(r.claimed_amount)} (${pct}% of sum insured ${money(r.sum_insured)})`,
  `  Incident date:    ${r.incident_date} (${policyAgeDays} days after policy start ${r.policy_start})`,
  `  Reported:         ${r.reported_at} via ${r.channel}`,
  '',
  'CLAIMANT DESCRIPTION (untrusted text)',
  `  ${String(r.description).replace(/\s+/g, ' ').slice(0, 1500)}`,
  '',
  'WHY IT WAS ROUTED HERE',
  ...(reasons.length ? reasons : ['  - (no reasons recorded)']),
  '',
  `SCORES  final ${r.final_risk_score ?? 'n/a'} | AI ${r.ai_risk_score ?? 'n/a'} (${r.ai_status}) | rules ${r.rule_score ?? 'n/a'}`,
  `AI SUMMARY  ${r.ai_summary || 'n/a'}`,
  `AI FRAUD INDICATORS  ${indicators}`,
  'RULE FLAGS',
  ...(flags.length ? flags : ['  - none']),
  '',
  'Use the button below to record your decision. Internal notes are never shown to the claimant;',
  'only "Message to claimant" is, and only when you request more information.',
].join('\n');

return [{ json: { claim_ref: r.claim_ref, subject: `[Fraud review] ${r.claim_ref} - ${r.product}, ${money(r.claimed_amount)}`, message } }];

// ── Read reviewer response ───────────────────────────────────────
// After send-and-wait resumes there are two cases:
//   * the reviewer submitted the form   -> the answer is on the item
//   * the wait limit was reached        -> no answer on the item (timeout)
// This node turns both into one shape: { responded, decision, status, template, ... }.
const ROUND = 1;
const it = $input.first().json;
const claim_ref = $('Build_Review_Message_Func').first().json.claim_ref;

// Form answers are keyed by field label. Look in `data` first, then the item itself.
const answers = (it.data && typeof it.data === 'object') ? it.data : it;
const get = (label) => {
  const key = Object.keys(answers).find((k) => k.trim().toLowerCase() === label.toLowerCase());
  return key === undefined ? undefined : answers[key];
};
const decisionLabel = get('Decision');

const DECISIONS = {
  'approve for assessment': { decision: 'approve', status: 'approved_for_assessment', template: 'approved_for_assessment' },
  'reject': { decision: 'reject', status: 'rejected', template: 'rejected' },
  'request more information': { decision: 'more_info', status: 'more_info_required', template: 'more_info_required' },
};

if (!decisionLabel) {
  return [{ json: { claim_ref, round: ROUND, responded: false } }];
}
const d = DECISIONS[String(decisionLabel).trim().toLowerCase()];
if (!d) throw new Error(`Fraud review ${claim_ref}: unexpected decision "${decisionLabel}"`);

return [{
  json: {
    claim_ref,
    round: ROUND,
    responded: true,
    ...d,
    reviewer: String(get('Reviewer email') || 'unknown').trim().toLowerCase().slice(0, 200),
    internal_notes: String(get('Internal notes') || '').trim().slice(0, 4000),
    message_to_claimant: d.decision === 'more_info' ? String(get('Message to claimant') || '').trim().slice(0, 2000) : '',
  },
}];

